3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
9	import org.springframework.web.bind.annotation.RequestBody;
10	
11	/**
12	 * First step of {@code POST /api/owners}. Rejects a body that is missing or blank in any
13	 * of firstName, lastName, address, city or telephone with a 400 (listing every offending
14	 * field) before the owner is built, then publishes the body for later steps.
15	 */
16	public class ValidateOwnerFields {
17	
18	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
19	            throws MissingOwnerFieldsException {
20	        List<String> missing = new ArrayList<>();
21	        if (isBlank(request.getFirstName())) {
22	            missing.add("firstName");
23	        }
24	        if (isBlank(request.getLastName())) {
25	            missing.add("lastName");
26	        }
27	        // Address is checked against its normalized form: an entry that collapses to blank once
28	        // whitespace is trimmed is rejected just as an absent one is.
29	        if (AddressNormalizer.normalize(request.getAddress()).isEmpty()) {
30	            missing.add("address");
31	        }
32	        if (isBlank(request.getCity())) {
33	            missing.add("city");
34	        }
35	        if (isBlank(request.getTelephone())) {
36	            missing.add("telephone");
37	        }
38	        if (!missing.isEmpty()) {
39	            throw new MissingOwnerFieldsException(missing);
40	        }
41	        validated.set(request);
42	    }
43	
44	    private static boolean isBlank(String value) {
45	        return value == null || value.trim().isEmpty();
46	    }
47	}
