4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerTelephoneException;
6	
7	/**
8	 * Normalizes the create-owner telephone into E.164 form: strips spaces, dashes and brackets,
9	 * keeps a leading '+' and country code when present, otherwise assumes country code '+61' and
10	 * drops a single leading '0' from the national digits, requiring 8 to 15 digits after the '+'.
11	 * Mutates the published request in place so later steps store and return the E.164 value.
12	 * Rejects anything that cannot form a valid E.164 number with a 400.
13	 */
14	public class NormalizeOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerTelephoneException {
17	        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
18	        if (e164 == null) {
19	            throw new InvalidOwnerTelephoneException(request.getTelephone());
20	        }
21	        request.setTelephone(e164);
22	    }
23	}
