1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	import java.util.regex.Pattern;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.rest.escalation.InvalidOwnerEmailException;
9	
10	/**
11	 * Normalizes the owner email when present: requires a syntactically valid address and
12	 * lower-cases it in place so later steps store and return the lower-cased value. An
13	 * absent or blank email is left untouched (email is optional). Rejects a present but
14	 * invalid email with a 400.
15	 */
16	public class NormalizeOwnerEmail {
17	
18	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidOwnerEmailException {
21	        String email = request.getEmail();
22	        if (email == null || email.trim().isEmpty()) {
23	            return;
24	        }
25	        if (!EMAIL.matcher(email).matches()) {
26	            throw new InvalidOwnerEmailException(email);
27	        }
28	        request.setEmail(email.toLowerCase(Locale.ROOT));
29	    }
30	}
